function usesIbpSupply(s){return s.supply==='ibp';}
function defineBaseSteps(s){
 const mts=s.scenario==='mts',mto=s.scenario==='mto',q=s.qty,h=s.heads,selected=getModulePlan(s).selectedDemand,engine=s.engine==='VC'?'classic VC':'AVC',ibp=usesIbpSupply(s);
 const define=(id,owner,icon,title,summary,tasks,output,next,explain)=>({id,owner,icon,title,summary,tasks,output,next,explain});
 const steps={
 foundation:define('foundation','Engineering + master data','FolderTree','Prepare product and manufacturing master data',`The journey starts before SO-1042. Engineering and manufacturing agree the structure; ${engine} supplies the configuration logic.`,['Transfer the eBOM into a manufacturing model; decide where fixed material variants are useful.','Maintain KMAT, class 300, characteristics, profile, dependencies, super-BOM and super-routing.','Maintain the production version, resources and times; generate the relevant PDS for PP/DS.'],'Valid product model + manufacturing source','Sales can value a configuration. MRP selects content. PP/DS uses the production source.','vc'),
 forecast:define('forecast','SAP IBP','ChartNoAxesCombined','Forecast printer volume and module mix',mts?`Plan 10 units of the selected ${h}-head stockable printer variant for the period.`:'Plan 10 Niagara-family printers for the period. The expected mix is six 5-head modules and four 7-head modules.',[mts?'Agree the forecast at the stockable variant and location level.':'Use illustrative attachment rates: 60% 5-head modules and 40% 7-head modules.',mto?'Use the model forecast as a demand/capacity outlook; this example does not release a final-printer PIR.':'Balance the agreed demand with the supply outlook.', 'Keep the baseline forecast separate from later order-consumption results.'],mts?'Forecast: 10 fixed-variant printers':'Model forecast: 10 · expected module mix: 6 / 4',mto?'The customer order will trigger operational supply. Long-lead preplanning could be added explicitly.':'Release only the intended planning level to S/4HANA.','ibp'),
 pir:define('pir','S/4 Demand Management','Database','Transfer the forecast to S/4 PIRs',mts?'The agreed forecast is transferred to a PIR for the fixed printer variant.':'The agreed module plan is transferred to PIRs at module level, not to an additional active printer PIR.',[mts?'Use strategy 40 with matching consumption settings.':'Illustrated module strategy: 70, with suitable collective requirements and consumption settings.',mts?'Initial printer PIR: 10 units in the eligible period.':'Initial print-module PIRs: 6 five-head modules and 4 seven-head modules.', 'Check product, plant, period and version mapping in the integration.'],mts?'S/4 printer PIR = 10':'S/4 module PIRs = 6 + 4; parent printer PIR = 0','PIRs create a planning signal. They do not create physical supply.','strategies'),
 mrpPre:define('mrpPre','MRP / procurement','ListFilter','Plan advance material supply',mts?'Net the printer PIR against available supply, then explode its selected manufacturing content.':'Net module PIRs against available supply; explode module BOMs into their required parts.', ['Apply net requirements, lot sizing and basic lead-time scheduling.','Create planned orders for in-house production and purchase requisitions for external parts.','Procurement follows through with purchase orders, supplier delivery, receipt and any inspection.'],mts?'Planned supply for 10 fixed-variant printers':'Planned module supply: 6 five-head + 4 seven-head','Critical in-house supply goes to the agreed PP/DS scope. Purchased parts must actually arrive.','mrp'),
 schedulePre:define('schedulePre','PP/DS','CalendarCheck','Schedule advance production',mts?'Sequence the operations needed to prebuild the fixed printer variants.':'Schedule the critical modules before the final customer configuration is known.', ['Use the PDS and relevant production resources.','Apply finite scheduling where capacity must constrain the plan.','Review dates, setup sequence and bottlenecks; resolve exceptions before execution.'],'Detailed production dates + resource sequence','The scheduling result supports release to the shop floor.','mrp'),
 releasePre:define('releasePre','Production execution','ClipboardCheck','Release work and stage the materials','Make the forecast-driven plan executable on the shop floor.', ['Convert the relevant planned orders into production orders.','Check component readiness and release the orders under the applicable controls.','Stage the parts and post production goods issue as they are consumed.'],'Released production orders + staged components','Production can now build the planned stock.','mrp'),
 buildPre:define('buildPre','Production execution + QM','Factory',mts?'Build and receive the fixed printer variant':'Build and receive common modules',mts?'Produce, assemble and inspect the 10 planned printers before a customer order exists.':`Produce the planned modules: ${selected} of the selected ${h}-head type are now available in this simplified example.`, ['Record operation confirmations and required quality checks.',mts?'Post finished-printer goods receipt to anonymous stock.':'Post module goods receipt to collective stock; no complete printer is built yet.', 'Receipt and stock status determine what is actually usable.'],mts?'10 ready printers in anonymous stock':'Module stock: 6 five-head + 4 seven-head; 0 finished printers','The customer order will consume the plan and use the relevant available supply.','modules'),
 order:define('order','Sales + '+engine,'FileCheck2','Create and configure the sales order',`SO-1042 requests ${q} printers, each with a ${h}-head print module, one feeder and one finishing module.`,[mts?'Select the exact stocked material variant; the customer choice must match its execution.':`Value the selected characteristics in ${engine}; reject modelled invalid combinations.`, 'Capture quantity, requested date, configuration and commercial conditions.', 'Send the planning demand and request the configured availability check. These branches can proceed independently.'],`Sales order SO-1042 / 10 · ${q} printers`,'S/4 now knows the order. IBP has not yet received or recalculated it in this staged example.','promise'),
 demand:define('demand','S/4 Demand Management','Database',mts?'Consume the matching printer PIR':'Create the order-specific printer requirement',mts?`${q} matching sales units consume ${Math.min(q,10)} of the initial 10 PIR units. The residual PIR is ${Math.max(10-q,0)}.`:`The configurable parent now has ${q} order-specific printer requirements. There is no parent PIR to consume in this design.`,[mts?`Effective printer demand is ${q} known + ${Math.max(10-q,0)} residual = ${Math.max(10,q)}.`:'Strategy 25 illustrates the order-specific parent requirement and stock segment.',!mts&&!mto?'The module PIRs are not simply decremented by the top-level sales order. Component requirements follow from the selected manufacturing content.':mto?'This example has no advance module PIRs. If they are added, define their consumption separately.':'Match the correct product, plant and consumption period.', 'No stock has been consumed by this demand-matching step.'],mts?`Open printer PIR ${Math.max(10-q,0)} + order ${q}`:`Parent order requirement ${q} · parent PIR 0`,'IBP and S/4 are still separate views until order integration and calculation have occurred.','consumption'),
 sync:define('sync','SAP IBP · illustrative demand view','Network','Integrate the order and calculate IBP consumption',`After integration and the configured planning calculation, IBP sees ${q} known units and ${Math.max(10-q,0)} units of open forecast.`, ['Retain the baseline forecast of 10 as the expectation used for comparison.','Use the assigned consumption profile, matching dimensions and eligible time window.',`The remaining demand is ${q} order units + ${Math.max(10-q,0)} open forecast = ${Math.max(10,q)}. Do not add the full forecast again.`],`Forecast 10 · relevant order ${q} · open forecast ${Math.max(10-q,0)}`,'At model level the total may still be covered. The selected module mix may tell a different story.','ibp'),
 mrp:define('mrp','MRP / procurement','ListFilter','Explode the concrete printer requirement',`The configuration requires ${q} feeders, ${q} ${h}-head print modules and ${q} finishing modules.`,[`Inside the selected print modules: ${q} × ${h} = ${q*h} individual print heads, before stock netting.`,mto?'Create order-driven proposals for the required modules and parts.':`Use the ${selected} prebuilt matching modules where available. The selected print-module shortfall is ${Math.max(0,q-selected)}.`, 'Net every material and stock segment; create missing in-house supply or procurement proposals. Firm and reschedule as needed.'],`Selected manufacturing requirements + supply proposals`,'In-house supply and final assembly go to detailed scheduling. External shortages must go through procurement.','modules'),
 schedule:define('schedule','PP/DS','CalendarCheck','Schedule order-specific production','Schedule the critical module supply and the final printer assembly in the relevant resource scope.', ['Use the selected manufacturing source and dates from the order requirement.','Check bottleneck resources, setup sequence and component-ready dates.','Resolve a capacity or material shortfall by changing supply or dates; no elapsed time is assumed in this demo.'],'Dated and sequenced supply for SO-1042','Use the resulting supply dates in the configured confirmation process.','mrp'),
 promise:define('promise','Sales / aATP','CalendarCheck','Confirm printer quantity and delivery date',mts?'The order can use the matching stock, subject to the configured checking scope.':'Review the customer promise against the supported checking route and the available or planned finished-printer supply.', ['Check the sold item, quantity, date and stock segment.','Use optional allocation, reprioritisation or alternative confirmation only where configured.','Record the confirmed quantity and date; this demo assumes a feasible date has been agreed.'],`Confirmation for ${q} printers · date agreed in the example`,'Confirmation does not itself build the printer or consume physical modules.','promise'),
 release:define('release','Production execution','ClipboardCheck','Release production and stage components','Convert and release the applicable production orders. Check and stage the required modules and parts.', ['Complete procurement or module production for any shortfalls.',!mto?`In the illustrated assembly-planning setup, eligible production requirements consume ${Math.min(q,selected)} of the ${selected} matching module PIR units.`:'No module PIR exists in this MTO example; supply is driven by the order requirements.', 'Issue physical components to production when consumed. Forecast consumption and goods issue remain different events.'],!mto?`Matching module residual plan: ${Math.max(0,selected-q)} · production order released`:'Released customer production orders + staged parts','Execute the build and inspection; retain traceability to the customer configuration.','modules'),
 build:define('build','Production execution + QM','Factory','Build, inspect and receive the customer printer',`Assemble ${q} printers in the selected execution and complete the required quality checks.`, ['Build any missing modules and record manufacturing confirmations.','Assemble the final printers, test them and resolve inspection exceptions.',`Post goods receipt for ${q} finished printers into the chosen sales-order stock E segment.`],`${q} customer-specific finished printers ready`,'Stock now exists for this order. Delivery can proceed against the relevant commitment.','ledger'),
 deliver:define('deliver','Logistics','Truck','Deliver and post goods issue',`Create the outbound delivery for ${q} printers, pick and pack the correct stock, then post goods issue.`, ['Check delivery readiness and the applicable order/stock segment.',`After PGI, open printer order quantity is 0; shipped quantity is ${q}.`,'In this period-accounting example, fulfilled quantities remain relevant to forecast reduction. The required delivery/actuals mapping must be configured; the forecast must not reopen incorrectly.'],`Outbound delivery + PGI · ${q} shipped printers`,'Update order and inventory information in the connected planning views, then invoice.','ibp'),
 invoice:define('invoice','Billing / Finance','FileCheck2','Invoice the delivery and record actuals','Create the invoice and complete applicable accounting and cost settlement.', ['Reconcile delivered quantities, billing and the order status.','Use actual sales and execution outcomes in subsequent planning cycles.','Review forecast accuracy, module mix and promise performance before revising the next plan.'],'Billing document + closed fulfilment loop','The next forecast cycle can use the actual outcome. It is a new planning decision, not an automatic rewrite at order entry.','ibp')
 };

 steps.supplyPlan=define('supplyPlan','SAP IBP · Supply','Network',mto?'Review shared supply and capacity':'Compare constrained supply scenarios',mto?'Review the common-component and shared-capacity outlook across MTS, MTO and CTO. This example does not prebuild the MTO printer or its modules.':mts?'Compare supply options for the fixed printer variant, its components and the relevant distribution network.':'Use the expected option mix to plan common modules, critical parts and shared capacity across the network.',[
 'Compare material availability, resource capacity, sourcing and timing assumptions; review shortages before selecting the plan.',
 mto?'Common-component buffers could be chosen in a different MTO design. Here they are not included in the stock numbers.':mts?'The accepted example plan covers 10 fixed-variant printers.':'The accepted example plan covers 6 five-head and 4 seven-head modules; final printers are not prebuilt.',
 'Keep the baseline demand forecast separate from constrained supply results. The explorer illustrates the process; it does not run an IBP optimizer.'
 ],mto?'Shared supply/capacity outlook; no advance order release':mts?'Accepted OBP supply plan for 10 printers':'Accepted OBP module supply plan: 6 + 4',mto?'The customer order still triggers the printer supply in S/4.':'Selected order-based proposals can now be handed over to S/4.','supply');
 steps.handover=define('handover','SAP IBP → S/4HANA','Network','Hand over planned orders',mts?'Transfer the accepted finished-variant supply proposals to S/4.':'Transfer the accepted common-module supply proposals to S/4.',[
 'Hand over the relevant OBP planned orders using the configured integration.',
 'Set planning ownership and horizons: in the illustrated delegated-scheduling scope, PP/DS sequences the handed-over supply; it does not independently create another plan for the same quantity.',
 'MRP/MM covers agreed remaining components and external procurement. A transferred planned order is supply, not a PIR or stock.'
 ],mts?'S/4 planned supply: 10 printer units':'S/4 planned module supply: 6 + 4','PIR transfer is left out of this example; other integration designs need aligned demand mapping and netting.','supply');
 steps.sbcCheck=define('sbcCheck','S/4 · aATP','ClipboardCheck','Request supply creation at order entry',`The customer requests ${q} configured printers. No matching finished-printer supply is ready in this example.`,[
 'Start the supported SBC checking route for this material and requirement.',
 'For a characteristic-dependent product, validate PPAC/CDP and the configuration integration; the VC/AVC label alone does not determine compatibility.',
 'The next diagram steps unpack a check within order entry; they do not require waiting for an IBP integration batch.'
 ],'New printer requirement sent to PP/DS','Existing usable components may still support the new printer supply. No finished printer does not mean no component supply.','sbc');
 steps.sbcPlan=define('sbcPlan','S/4 · PP/DS','CalendarCheck','Simulate supply before confirmation',`Plan the new ${q}-printer requirement in the configured SBC scope.`,[
 `Consider selected components (${q} matching print modules) and the relevant resource capacity.`,
 'Check feasible procurement/production timing. Proposed orders and dates are planning results, not physical receipts or goods issue.',
 'If the check is successful, pass the result back to aATP; accepted planning results become operative supply according to the SBC process.'
 ],'Feasible supply dates/quantities, or a shortfall','The simulation plans the new requirement; it does not rerun MRP for the entire plant. The demo follows the successful path without calculating a date.','sbc');
 if(ibp){
  steps.forecast.tasks[1]=mto?'Use the forecast to review shared capacities and common-part choices.':'Pass the agreed demand and mix into IBP supply scenario planning.';
  steps.forecast.explain='supply';
  steps.forecast.next='Demand is an input to supply planning, not an executable production order.';
  steps.schedulePre.explain='supply';
  steps.schedulePre.summary='Sequence the accepted, handed-over supply within the agreed PP/DS scheduling scope.';
  steps.schedulePre.tasks[2]='Return detailed dates and execution changes to IBP; respect the chosen ownership and freeze horizons.';
  steps.buildPre.next='The customer order uses matching available supply. Reconcile order demand and forecast in IBP; this example has no additional S/4 PIR transfer.';
  if(mts){steps.demand.title='Create the customer requirement';steps.demand.summary=`S/4 records ${q} printer units for the customer. Supply was already planned in IBP and prebuilt in this example.`;steps.demand.tasks=['No S/4 printer PIR is transferred in this order-based handover example.','The order and its subsequent updates are integrated into the configured IBP demand view.','Demand creation is separate from allocating or issuing physical stock.'];steps.demand.output=`Customer requirement ${q} · no additional S/4 PIR`;}
  if(!mts){steps.demand.tasks[1]=mto?'Common-part buffers can be planned separately; none are counted here.':'Selected component needs are netted against existing module supply. No module PIR is transferred in this IBP-led example.';steps.release.tasks[1]=mto?'Retain accepted order-driven supply; no module PIR is present.':'Use the selected module stock and complete shortages; reconcile supply changes with IBP. No S/4 module PIR is consumed in this route.';steps.release.output='Released customer production orders + staged parts';}
 }
 if(mto){
  steps.promise.title='Confirm from the SBC result';steps.promise.summary='aATP uses the PP/DS result to establish the customer quantity and date.';
  steps.promise.tasks=['The illustrated simulation succeeded; a feasible date is agreed.','If the requested date or quantity cannot be met, review the proposal or leave the requirement unconfirmed for follow-up.','Saving the sales order finalizes the customer reference; operational execution follows.'];steps.promise.explain='sbc';
  steps.mrp.explain='sbc';steps.schedule.explain='sbc';
  steps.mrp.title='Complete procurement and supply follow-up';steps.mrp.summary='Follow through on the accepted SBC supply and any remaining component-planning work.';
  steps.mrp.tasks[1]='Retain the accepted order-driven proposals; do not create duplicate supply from the same demand.';
  steps.mrp.next='Complete purchasing and production preparation; manage changes to the accepted plan.';
  steps.schedule.title='Maintain the detailed production plan';steps.schedule.summary='Prepare execution and keep the accepted order plan aligned with material and resource changes.';steps.schedule.next='A material or capacity change may require reconsidering the confirmation. This is follow-up to the SBC plan.';
 }
 return steps;
}
